from pathlib import Path
import hashlib, json
root = Path('products/distribution/sqlite-curated-tools')
draft = root / 'operator-listing-draft.json'
files = []
for path in sorted(root.glob('*.json')):
    if path.name == 'director-handoff-readback.json':
        continue
    raw = path.read_bytes()
    try:
        data = json.loads(raw)
    except ValueError:
        continue
    if not isinstance(data, dict):
        continue
    fields = {k: v for k, v in data.items() if any(term in k.lower() for term in ('verdict', 'decision', 'policy', 'permission', 'eligib', 'route', 'status', 'trigger', 'conclusion'))}
    files.append({'path': str(path), 'sha256': hashlib.sha256(raw).hexdigest(), 'fields': fields})
result = {'draft_path': str(draft), 'draft_sha256': hashlib.sha256(draft.read_bytes()).hexdigest() if draft.is_file() else None, 'records': files, 'coverage': 'Top-level JSON in the public placement directory only. A missing decision in this inventory does not establish that no operator decision exists.'}
out = root / 'director-handoff-readback.json'
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n')
print(out.read_text()[:5500])
